# Virtual DualSense USB over physical DualSense USB (wired).
# Full passthrough: the virtual device IS the physical device, so input,
# output, and feature requests are forwarded verbatim. No BT reformatting,
# no CRC signing, no report reshaping.
#
# Report IDs are left at 0, which selects the runtime's passthrough paths
# (translate_controller_input/output copy the whole report verbatim and
# ignore the copy range). The copy = lines below are required by the map
# loader's validation but are NOT used at runtime in passthrough mode.

# ISO audio passthrough IS implemented -- see [path.iso.virtual_to_physical_
# stream] passthrough at the bottom of this file. The virtual USB ISO stream is
# forwarded to the client as raw PCM (MsgIsoAudio), bypassing the Opus/reservoir
# pipeline that Bluetooth uses. A wired controller is a USB audio device on the
# client side, so the client writes those samples to it directly.
# NOTE: this requires a client that implements MsgIsoAudio and writes to the
# controller's audio device. Against a client that does not, the flag is inert.
# Speaker audio (channels 0/1) confirmed working end-to-end 2026-07-28.
# NOT YET VERIFIED: haptic audio on channels 2/3. The full 4-channel chunk is
# forwarded verbatim so it should arrive, but no test has confirmed the client
# writes it to the haptic channels. Do not assume it works.
# Buttons, sticks, adaptive triggers, LEDs, and feature reports all work.


[map]
id = ds5_usb_over_ds5_usb
version = 1
virtual_device = ds5_usb
physical_device = ds5_usb

[usb.endpoints]
hid_in = 0x84
hid_out = 0x03

[path.input.controller_to_virtual]
trigger = physical.read
destination_length = 64
copy = source[0..63] -> destination[0..63]

[path.output.virtual_to_controller]
trigger = usb.endpoint.hid_out
destination_length = 64
copy = source[0..63] -> destination[0..63]

[advertise]
controller_name = DualSense (Wired)
vendor = Sony
rumble = true
leds = true
adaptive_triggers = true
haptics = true
audio_output = true
audio_input = false
battery = true

[path.iso.virtual_to_physical_stream]
# wired: skip Opus/BT pipeline, send raw PCM via MsgIsoAudio.
# Comment MUST stay on its own line -- the INI parser does not strip
# trailing comments, so an inline one becomes part of the value and the
# flag silently reads false.
passthrough = true
